// Generated by vibelang from src/features/flows-ui/api.ts; the migrate flow writes it again with each batch.
import { Context, Effect, Layer, Option, Schema } from "effect";
import { HttpClient, HttpClientRequest } from "effect/http";
import { FLOW_DRAFTS_ROUTE, FLOWS_ROUTE } from "./contract.js";
import { FlowNotFound, FlowsRefused, FlowsUnavailable } from "./reference.js";
import { Draft, DraftList, FlowList, FlowSource, FlowsRefusal, Saved, Written, } from "./schema.js";
// ChatApi's flows and drafts routes as `flow/*`'s steps call them (worker/PersonalFlows.ts), through Effect's
// HttpClient, each exchange under one deadline. A refusal (4xx) is `FlowsRefused` with ChatApi's code, final; no answer,
// a deadline or a 5xx is `FlowsUnavailable`, which a step's retry policy tries again.
/** How long a step gives ChatApi to answer. */
export const REQUEST_WITHIN = "15 seconds";
const decodeRefusal = Schema.decodeUnknownOption(Schema.fromJsonString(FlowsRefusal));
/** Reads ChatApi's personal flows routes on `origin`. */
export class FlowsClient extends Context.Service()("@smthrs/mvp/flows/FlowsClient") {
    /** The client over the host's `HttpClient`, each request answered within `within`. */
    static layer = (options) => Layer.effect(FlowsClient, Effect.gen(function* () {
        const client = yield* HttpClient.HttpClient;
        const within = options.within ?? REQUEST_WITHIN;
        /** One exchange: `request`'s answer decoded by `schema`, a 404 as `notFound` when given. */
        const exchange = (request, schema, notFound) => 
        // Every route answers JSON: a `{ code }` refusal, or the value `schema` reads.
        Effect.gen(function* () {
            const response = yield* client.execute(request).pipe(Effect.mapError(() => new FlowsUnavailable({})));
            yield* Effect.annotateCurrentSpan({ "http.response.status_code": response.status });
            if (response.status === 404 && notFound !== undefined)
                return yield* Effect.fail(notFound);
            if (response.status >= 400 && response.status < 500) {
                // A body that can't be read reads as no code.
                const body = decodeRefusal(Option.getOrUndefined(yield* Effect.option(response.text)));
                return yield* new FlowsRefused({
                    status: response.status,
                    code: Option.match(body, { onNone: () => "refused", onSome: ({ code }) => code }),
                });
            }
            if (response.status !== 200)
                return yield* new FlowsUnavailable({ status: response.status });
            return yield* response.json.pipe(Effect.flatMap(Schema.decodeUnknownEffect(schema)), Effect.mapError(() => new FlowsUnavailable({ status: response.status })));
        }).pipe(
        // Interrupting the request aborts its fetch, so a stalled body stops too.
        Effect.timeoutOrElse({ duration: within, orElse: () => Effect.fail(new FlowsUnavailable({})) }));
        const post = (path, body) => HttpClientRequest.post(`${options.origin}${path}`).pipe(HttpClientRequest.bodyJsonUnsafe(body));
        const get = (path) => HttpClientRequest.get(`${options.origin}${path}`);
        return FlowsClient.of({
            list: exchange(get(FLOWS_ROUTE), FlowList).pipe(Effect.withSpan("flow.client.list")),
            source: (name, revision, flowId) => exchange(get(`${FLOWS_ROUTE}/source?name=${encodeURIComponent(name)}${revision === undefined ? "" : `&revision=${revision}`}${flowId === undefined ? "" : `&flowId=${flowId}`}`), FlowSource, new FlowNotFound()).pipe(Effect.withSpan("flow.client.source")),
            draft: (draftId) => exchange(get(`${FLOW_DRAFTS_ROUTE}/${draftId}`), Draft).pipe(Effect.withSpan("flow.client.draft")),
            drafts: exchange(get(FLOW_DRAFTS_ROUTE), DraftList).pipe(Effect.withSpan("flow.client.drafts")),
            writeDraft: (draftId, write) => exchange(post(`${FLOW_DRAFTS_ROUTE}/${draftId}`, write), Written).pipe(Effect.asVoid, Effect.withSpan("flow.client.write_draft")),
            answer: (draftId, answers) => exchange(post(`${FLOW_DRAFTS_ROUTE}/${draftId}/answers`, answers), Written).pipe(Effect.asVoid, Effect.withSpan("flow.client.answer")),
            save: (request) => exchange(post(`${FLOWS_ROUTE}/save`, request), Saved).pipe(Effect.withSpan("flow.client.save")),
            write: (request) => exchange(post(`${FLOWS_ROUTE}/write`, request), Saved, new FlowNotFound()).pipe(Effect.withSpan("flow.client.write")),
            remove: (flowId) => exchange(post(`${FLOWS_ROUTE}/${flowId}/delete`, {}), Written, new FlowNotFound()).pipe(Effect.as(true), 
            // Not the person's, or deleted already: nothing to delete.
            // expected: a flow already gone answers false
            Effect.catchTag("@smthrs/mvp/flows/FlowNotFound", () => Effect.succeed(false)), Effect.withSpan("flow.client.delete")),
            deleteDraft: (draftId) => exchange(post(`${FLOW_DRAFTS_ROUTE}/${draftId}/delete`, {}), Written, new FlowNotFound()).pipe(Effect.as(true), 
            // Gone already, or never the person's to read.
            // expected: a draft already gone answers false
            Effect.catchTag("@smthrs/mvp/flows/FlowNotFound", () => Effect.succeed(false)), Effect.withSpan("flow.client.delete_draft")),
        });
    }));
}
